import google.generativeai as genai
import os

class ImageSummaryRequest:
    def __init__(self, labels: list[str], description: str, detected_text: str, safety_labels: list[str]):
        self.labels = labels
        self.description = description
        self.detected_text = detected_text
        self.safety_labels = safety_labels

class ImageSummaryResponse:
    def __init__(self, summary: str):
        self.summary = summary

def image_summary(request: ImageSummaryRequest) -> ImageSummaryResponse:
    # Configure the Google Generative AI API client
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel('gemini-pro')

    prompt = f"""Summarize the following image analysis results:
Labels: {', '.join(request.labels)}
Description: {request.description}
Detected Text: {request.detected_text}
Safety Labels: {', '.join(request.safety_labels)}
"""

    response = model.generate_content(prompt)
    return ImageSummaryResponse(summary=response.text)

from google.cloud import translate_v2 as translate
import os

class AltTextTranslateRequest:
    def __init__(self, text: str, target_language: str):
        self.text = text
        self.target_language = target_language

class AltTextTranslateResponse:
    def __init__(self, translated_text: str):
        self.translated_text = translated_text

def alt_text_translate(request: AltTextTranslateRequest) -> AltTextTranslateResponse:
    translate_client = translate.Client()
    result = translate_client.translate(request.text, target_language=request.target_language)
    return AltTextTranslateResponse(translated_text=result['translatedText'])

from google.cloud import language_v1

class VisualSafetyTextRequest:
    def __init__(self, text: str):
        self.text = text

class VisualSafetyTextResponse:
    def __init__(self, is_safe: bool, sentiment_score: float):
        self.is_safe = is_safe
        self.sentiment_score = sentiment_score

def visual_safety_text(request: VisualSafetyTextRequest) -> VisualSafetyTextResponse:
    client = language_v1.LanguageServiceClient()
    document = language_v1.Document(content=request.text, type_=language_v1.Document.Type.PLAIN_TEXT)
    sentiment = client.analyze_sentiment(request={"document": document}).document_sentiment

    # For simplicity, let's consider a negative sentiment score as potentially unsafe.
    # Threshold can be adjusted based on requirements.
    is_safe = sentiment.score >= -0.2

    return VisualSafetyTextResponse(is_safe=is_safe, sentiment_score=sentiment.score)

